<template>
  <v-card
      class="mx-auto cursor-pointer text-center"
      max-width="450"
  >
    <div class="font-bold big text-start pb-5 pl-3">
      Total:&nbsp; <span class="price">{{ amount }}</span>
    </div>
    <v-img
        class="zoom-on-hover"
        height="300"
        width="400"
        :src="src"
        cover
        loading="lazy"
    >
    </v-img>
    <v-card-text>
      Customer will be redirected on brand checkout page
    </v-card-text>
    <v-card-actions class="justify-center pb-5">
      <v-btn
          text="Pay"
          variant="flat"
          :color="colors.primary"
          @click="redirect"
      >
      </v-btn>
    </v-card-actions>
  </v-card>
</template>

<script>
import colors from "@/utils/colors.js";

export default {
  name: "RedirectWidget",
  props: {
    amount: 0,
    src: '',
  },
  methods: {
    redirect() {
      const cardData = {
        amount: this.amount * 100,
        merchant_id: 1549901,
        currency: 'GEL',
        lang: 'en',
        payment_system: "card",
      };
      window.$checkout('Api').scope(function () {
        this.request('api.checkout.form', 'request', cardData).done(function (model) {
          console.log(model);
        }).fail(function (model) {
          const uri = 'https://pay.flitt.com/merchants/6aa79957f6f8336b820e6c82b7634f0c/default/index.html?token=' + model.data.token
          window.location.href = uri;
        });
      });

    },
  },
  data() {
    return {
      colors: colors
    };
  },
};
</script>